 langid = {english},
 abstract = {We consider the generalized movers' problem i.e. finding any path that moves an object to a desired goal while avoiding collisions. Even relaxing optimality requirements, the any-path problem is computationally challenging. Namely, exponential in the degrees of freedom of the object. Due to the curse of dimensionality, applying traditional search algorithms to the discretized state space becomes infeasible as the state space grows. This motivated the use of sampling-based methods. These sampling-based methods are tabula rasa and require complete re-learning on each problem instance. Existing learning-based methods that attempt to leverage shared structure aim to handle arbitrary changes in the environment. Often, this still requires a significant number of samples and / or expert demonstrations. In practice, many robotics applications or UAV routing do not need to handle these pathological cases, where the environment undergoes drastic change. Rather, they must only be able to avoid a minor mismatch with the training environment while their route remains largely unchanged. We allow pre-training in an obstacle free environment and show that combining contrastive reinforcement learning with classical game-inspired search algorithms enables zero shot performance to unseen obstacles.}
}

fr:mainmatter.fr:tex:
\begin {align*}
    \mathbb {P}(z_t \mid  x_{0}, \ldots , x_{T}) &= \frac {\mathbb {P}(x_{0}, \ldots , x_{T} \mid  z_t)\mathbb {P}(z_t)}{\mathbb {P}(x_{0}, \ldots , x_{T})} \\
&= \frac {\mathbb {P}(x_{t + 1}, \ldots , x_{T} \mid  z_t, x_{0}, \ldots , x_t) \mathbb {P}(x_{0}, \ldots , x_{t} \mid  z_t)\mathbb {P}(z_t)}{\mathbb {P}(x_{0}, \ldots , x_{T})} \\
&= \frac {\mathbb {P}(x_{t + 1}, \ldots , x_{T} \mid  z_t, x_{0}, \ldots , x_t) \mathbb {P}(x_{0}, \ldots , x_{t}, z_t)}{\mathbb {P}(x_{0}, \ldots , x_{T})}
  .\end {align*}

fr:tree.fr:mainmatter:
\begin {align*}
  \phi _t(z) &= \mathbb {P}(x_{0}, \ldots , x_t, z) \\
  &= \mathbb {P}(x_0, \ldots , x_t \mid  z) \mathbb {P}(z) \\
  &= \mathbb {P}(x_0, \ldots , x_{t - 1} \mid  x_t, z) \mathbb {P}(x_t \mid  z) \mathbb {P}(z)
.\end {align*}
Since this is a HMM, (x_{0}, \ldots , x_{t - 1}) \perp  x_{t} \mid  z_{t}. Therefore, we can drop the x_t from the first term, such that
\begin {align*}
  \phi _t(z) &= \mathbb {P}(x_0, \ldots , x_{t - 1} \mid  z) \mathbb {P}(x_t \mid  z) \mathbb {P}(z) \\
  &= \mathbb {P}(x_0, \ldots , x_{t - 1}, z) \mathbb {P}(x_t \mid  z) \\
  &= \mathbb {P}(x_t \mid  z) \sum _{z'} \mathbb {P}(x_0, \ldots , x_{t - 1}, z', z)  \\
  &= \mathbb {P}(x_t \mid  z) \sum _{z'} \mathbb {P}(x_0, \ldots , x_{t - 1} \mid  z', z) \mathbb {P}(z \mid  z') \mathbb {P}(z')
.\end {align*}
Similarly, (x_{0}, \ldots , x_{t - 1}) \perp  z_{t} \mid  z_{t - 1}, such that
\begin {align*}
   \phi _t(z) &= \mathbb {P}(x_t \mid  z) \sum _{z'} \mathbb {P}(x_0, \ldots , x_{t - 1} \mid  z') \mathbb {P}(z \mid  z') \mathbb {P}(z') \\
&= \mathbb {P}(x_t \mid  z) \sum _{z'} \mathbb {P}(x_0, \ldots , x_{t - 1}, z') \mathbb {P}(z \mid  z') \\
&= \mathbb {P}(x_t \mid  z) \sum _{z'} \phi _{t - 1}(z') \mathbb {P}(z \mid  z')
.\end {align*}

Here z' ranges over the possible values of z_{t - 1}. We see that \phi _t(z) depends only on information from time t and t - 1. Therefore, information propagates forward in time.

\begin {align*}
  \beta _t(z) &= \mathbb {P}(x_{t + 1}, \ldots , x_{T} \mid  z) \\
  &= \sum _{z'} \mathbb {P}(x_{t + 1}, \ldots , x_{T}, z' \mid  z) \\
  &= \sum _{z'} \mathbb {P}(x_{t + 2}, \ldots , x_{T} \mid  x_{t + 1}, z', z) \mathbb {P}(x_{t + 1} \mid  z', z) \mathbb {P}(z' \mid  z)
.\end {align*}
First, since this is a HMM, everything is independent of z_{t} given z_{t + 1}. Therefore, we can simplify
\begin {align*}
  \beta _t(z) &= \sum _{z'} \mathbb {P}(x_{t + 2}, \ldots , x_{T} \mid  x_{t + 1}, z') \mathbb {P}(x_{t + 1} \mid  z') \mathbb {P}(z' \mid  z).
\end {align*}
Additionally, (x_{t + 2}, \ldots , x_{T}) \perp  x_{t + 1} \mid  z_{t + 1}, such that
\begin {align*}
  \beta _t(z) &= \sum _{z'} \mathbb {P}(x_{t + 2}, \ldots , x_{T} \mid  z') \mathbb {P}(x_{t + 1} \mid  z') \mathbb {P}(z' \mid  z) \\
&= \sum _{z'} \beta _{t + 1}(z') \mathbb {P}(x_{t + 1} \mid  z') \mathbb {P}(z' \mid  z)
.\end {align*}

Here z' ranges over the possible values of z_{t + 1}. We see that \beta _t(z) depends only on information from time t and t + 1. Therefore, information propagates backward in time.

